CREATE TABLE IF NOT EXISTS launch_gates(gate_id TEXT PRIMARY KEY,release_id TEXT NOT NULL,name TEXT NOT NULL,required INTEGER NOT NULL,status TEXT NOT NULL,evidence_ids_json TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS change_windows(change_id TEXT PRIMARY KEY,starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,owner TEXT NOT NULL,rollback_ref TEXT NOT NULL,approved INTEGER NOT NULL DEFAULT 0);